class DictUnpackingTransformer:
    """Compiles:

            {1: 1, **dict_a}

        To:

            _py_backwards_merge_dicts([{1: 1}], dict_a})

    """
    target = 3, 4

    def _merge_dicts(self, xs: Iterable[Union[ast.Call, ast.Dict]]) -> ast.Call:
        """Creates call of function for merging dicts."""
        return ast.Call(
            func=ast.Name(id='_py_backwards_merge_dicts'),
            args=[ast.List(elts=list(xs))],
            keywords=[])
